WITH metrics AS (SELECT id, session_id, page, duration_sec, LEAD(duration_sec) OVER w_part AS next_duration_sec, LAG(duration_sec) OVER w_part AS prev_duration_sec, ROW_NUMBER() OVER w_part AS seq_no, ROW_NUMBER() OVER (PARTITION BY page ORDER BY duration_sec, id) AS event_seq FROM web_events WINDOW w_part AS (PARTITION BY page, session_id ORDER BY event_time, id)) SELECT s.id, s.session_id, s.page, s.duration_sec, s.next_duration_sec, s.prev_duration_sec, s.seq_no, s.event_seq, (SELECT AVG(x.duration_sec) FROM web_events x WHERE x.session_id = s.session_id) AS avg_web_event_duration_sec FROM metrics s;
